#include <stdio.h>

void reverseArray(int arr[], int n) {
    int i = 0, j = n - 1;
    while(i < j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++; j--;
    }
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int arr[n];
    for(int i = 0; i < n; i++) scanf("%d", &arr[i]);
    reverseArray(arr, n);
    for(int i = 0; i < n; i++) printf("%d%c", arr[i], (i == n-1 ? 10 : 32));
    return 0;
}

